from taf.ul.trs_e2e_fw.lib.oam.exceptions import BtsNotOnAirException


logger = BackgroundLogger.Instance()
standard_library.install_aliases()
default_egate_edaemon_ports = [20000, [10000]]


class iphy(UE):

    def __init__(self, device_details, device_name, dut, rat, **kwargs):
        self.wtssim = ute_wtssim()
        self.device_details = device_details
        self.ue_type = "iphy"
        self.device_name = device_name
        self.relative_cfg_path = os.path.join(ConfigHandler.config['common_resources_path'])
        self.egate_alias = None
        setup_wtssim = kwargs.pop("setup_wtssim", True)
        self.timeout = kwargs.pop("timeout", 1200)
        self.attach_flag = kwargs.pop("attach", True)
        should_be_onair = kwargs.pop('should_be_onair', True)
        self.te_id = TeId(dut, rat)
        self.rat = rat
        self.store = Store()
        self.config = ConfigHandler.get_config()
        # self.ue_ids = kwargs.get("ue_ids", "1")
        self.attach_arguments = kwargs

        if setup_wtssim:
            self._retry_on_failure_setup_wtssim(device_details, should_be_onair)

    def call_start(self, call_type="data", iperf_section=None, profile=None, **kwargs):
        if call_type.lower() == 'data':
            if profile is None:
                raise ProfileNotPassedException
            profile_params = get_config_variable(['traffic_profiles', profile])
            ue_ids = kwargs.get("ue_ids", "1")
            ue_id_list = self._get_ue_id_list(ue_ids)
            self.generator = profile_params.pop("generator", "iperf")
            iperf_obj_list = []
            if self.generator != "iperf":
                # for multiple ue ids and cell ids we have to run a loop
                # self.wtssim.execute_egate_command(
                #   cmd="data_start", ue_id = self.ue_id, id=self.cell_id,
                # alias = self.egate_alias, **profile_params)
                self._data_start(profile, profile_params, ue_ids)
            elif self.generator == "iperf":
                for ue_id in ue_id_list:
                    ueip = self._get_nat_and_ue_ips(iperf_section, ue_id)
                    iperf = Iperf(ueip, iperf_section, profile, self.ue_type, self.rat, self.device_name)
                    iperf_obj_list.append(iperf)
                    iperf.start_data(profile)
                self.store.add(iperf_obj_list, alias=profile)
            else:
                raise Exception(
                    'Unsupported Generator {}, Supported Generators iphy, '
                    'iperf'.format(self.generator))

    def call_stop(self, call_type="data", profile=None):
        if call_type.lower() == 'data':
            if self.generator == 'iperf':
                iperf_obj_list = self.store.get(alias=profile)
                for iperf in iperf_obj_list:
                    throughput_fields = iperf.stop_data(profile)
                    self.store.remove(alias=profile)
                    return throughput_fields
            else:
                self._data_stop(profile)

    def attach(self, verify_teid=False, call_type="data"):
        if self.attach_flag:
            if verify_teid:
                initial_iwf_value = self.te_id.get_te_id()
            pass_regex = self._generate_attach_verification_string()

            attach_arguments = self._get_attach_arguments()
            self.wtssim.execute_egate_command(
                "ue_attach {}".format(attach_arguments),
                pass_regexp=pass_regex, alias=self.egate_alias, timeout=30)
            if verify_teid:
                self.te_id.check_iwf_value_increased(initial_iwf_value)
            time.sleep(5)
            # return self._retreive_ueip()

    def detach(self, **kwargs):
        if self.attach_flag:
            ue_ids = kwargs.get("ue_ids", self.ue_ids)
            self.wtssim.execute_egate_command(cmd="ue_detach id={}".format(
                ue_ids), pass_regexp=".*UE\\d+:\\sdetached",
                alias=self.egate_alias)

    def configure_ue(self, **kwargs):
        command = kwargs.get('command')
        timeout = kwargs.get('timeout', 10)
        output = self.wtssim.execute_egate_command(cmd=command, timeout=timeout, alias=self.egate_alias)
        time.sleep(2)
        return output

    def call_teardown(self):
        self.wtssim.teardown_all_aliases_for_egate()
        self.wtssim.teardown_all_aliases_for_edaemon()

    def _retry_on_failure_setup_wtssim(self, device_details, should_be_onair):
        attempt = 1
        while attempt <= 3:
            self._setup_wtssim(device_details)
            admin_alias = _setup_oam_ops()
            if should_be_onair:
                try:
                    bts_status = CellOperations().verify_bts_status(req_rat=self.rat, should_be_onair=should_be_onair,
                                                                    alias=admin_alias)
                    if bts_status:
                        break
                except Exception as e:
                    logger.warn("Attempt {} :: Expected rat {} is not onAir : {}".format(attempt, self.rat, e))
                    self._teardown_wtssim(device_details=device_details)
                finally:
                    attempt += 1
            else:
                break
        else:
            raise BtsNotOnAirException

    def _setup_wtssim(self, device_details):
        lua_files_dict = self._get_lua_file_and_ports(device_details)
        for lua_file, ports in list(lua_files_dict.items()):
            lua_file = os.path.join(self.relative_cfg_path, lua_file)
            logger.info("lua file path {}".format(lua_file))
            if not os.path.exists(lua_file):
                raise Exception('Lua File {} Does not Exist'.format(lua_file))
            egate_port, edaemon_ports = ports
            self.wtssim.start_wts_applications(egate_port=egate_port, edaemon_ports=edaemon_ports, cfg_file=lua_file)
        # self.wtssim.start_wts_services(device_details.get('timeout', 1200), alias=self.egate_alias)
        self.wtssim.start_wts_services(timeout=self.timeout, alias=self.egate_alias)

    def _teardown_wtssim(self, device_details):
        self.wtssim.stop_and_collect_wts_logs()

    def _get_lua_file_and_ports(self, device_details):
        lua_files_dict = device_details["cfg_file"]
        if not isinstance(lua_files_dict, dict):
            if not isinstance(lua_files_dict, list):
                lua_files_dict = lua_files_dict.split()
            lua_files_dict = {lua: default_egate_edaemon_ports for lua in lua_files_dict}
        return lua_files_dict

    def _retreive_ueip(self, ue_id):
        egate_options = self._generate_egate_options_string(
            {"id": ue_id, "at": "ue"})
        output = self.wtssim.execute_egate_command_and_wait_for_data(
            cmd="ue_disp " + egate_options, alias=self.egate_alias)
        return output["UE Ip"]

    def _retreive_natip(self, ue_id):
        # egate_options = self._generate_egate_options_string(
        #    {"id": ue_id, "at": "ue"})
        output = self.wtssim.execute_egate_command_and_wait_for_data(
            cmd="ue_disp", id=self.ue_id, at="ue", alias=self.egate_alias)
        return output['UE NAT Ip']

    def _get_attach_arguments(self):
        self.ue_ids = self.attach_arguments.get('ue_ids', '1')
        selected_plmn = self.attach_arguments.get('selected_plmn')
        if selected_plmn:
            return 'id={} selected_plmn={}'.format(self.ue_ids, selected_plmn)
        else:
            return 'id={}'.format(self.ue_ids)
        # ' '.join(['{}={}'.format(
        #     name, val) for name, val in self.attach_arguments.items()])

    def _generate_attach_verification_string(self):
        # ue_id_list = self._get_ue_id_list(ue_ids)
        pass_regex = ""
        # for ue_id in ue_id_list:
        #    pass_regex += ".*UE{}:\\s===\\sUE\\sIS\\sACTIVE".format(ue_id)
        pass_regex = ".*UE\\d+:\\s===\\sUE\\sIS\\sACTIVE"
        logger.info("Attach verification string: {}".format(pass_regex))
        return pass_regex

    def _get_ue_id_list(self, ue_ids):
        if "," in ue_ids:
            ue_id_list = ue_ids.split(",")
        elif "-" in ue_ids:
            ue_ids_range = ue_ids.split("-")
            ue_id_list = list(range(int(ue_ids_range[0]), int(ue_ids_range[1])))
        else:
            ue_id_list = ue_ids
        logger.info("UE ID list:{}".format(ue_id_list))
        return ue_id_list

    def _data_start(self, profile, profile_params, ue_ids):
        egate_options = self._generate_egate_options_string(profile_params)
        self.wtssim.execute_egate_command(cmd="data_start " + egate_options, alias=self.egate_alias)
        self.store.add((ue_ids, profile_params["id"]), alias=profile)

    def _data_stop(self, profile):
        ue_ids, bearer_id = self.store.get(alias=profile)
        # self.wtssim.execute_egate_command(
        #     cmd="data_stop id={} ue={}".format(self.cell_id, self.ue_id),
        #     alias=self.egate_alias)
        egate_options = self._generate_egate_options_string({"id": bearer_id,
                                                             "ue": ue_ids})
        self.wtssim.execute_egate_command(cmd="data_stop " + egate_options,
                                          alias=self.egate_alias)
        self.store.remove(alias=profile)

    def _generate_egate_options_string(self, profile_params):
        egate_command = ""
        for key, value, in list(profile_params.items()):
            egate_command += "{}={} ".format(key, value)
        return egate_command

    def _get_nat_and_ue_ips(self, iperf_section, ue_id):
        ueip = self._retreive_ueip(ue_id)
        self.config['iperf'][iperf_section]['ip'] =\
            set_config_variable(['iperf', iperf_section, 'ip'], ueip)
        return ueip

